<script setup lang="ts">import{ref}from'vue';defineProps<{demo?:boolean}>();const confirmRoom=ref<null|{title:string;coins:number}>(null);const entering=ref(false);const anchors=[{name:'姜姜',title:'今晚八点 · 陪你聊日常',coins:20,color:'#ff7d8f',online:true},{name:'小鹿',title:'旅行碎片和幕后花絮',coins:10,color:'#8675ff',online:true},{name:'一一',title:'预约一对一交流',coins:30,color:'#ffad5c',online:false}];function enter(a:typeof anchors[number]){confirmRoom.value={title:a.title,coins:a.coins};}function confirm(){entering.value=true;confirmRoom.value=null;}</script>
<template><main class="page home-page"><header class="hero"><div><span class="eyebrow">ANCHOR CIRCLE</span><h1>正在发生的<br><strong>精彩现场</strong></h1></div><button class="round-button" aria-label="搜索">⌕</button></header><section class="quick-row"><article><span>🔥</span><div><b>热门直播</b><small>实时互动</small></div></article><article><span>◎</span><div><b>主播圈子</b><small>专属动态</small></div></article></section><section class="section-head"><div><span class="live-dot"></span><h2>正在直播</h2></div><a>查看全部</a></section><section class="anchor-grid"><article v-for="(anchor,index) in anchors" :key="anchor.name" class="anchor-card"><div class="cover" :style="{background:`linear-gradient(145deg,${anchor.color},#241e45)`}"><span class="live-badge">{{anchor.online?'LIVE':'预约'}}</span><div class="portrait" aria-hidden="true">{{['姜','鹿','一'][index]}}</div><span class="viewer-count">◉ {{128-index*31}}</span></div><div class="card-copy"><h3>{{anchor.name}}</h3><p>{{anchor.title}}</p><div><span class="coin">◈ {{anchor.coins}} 金币</span><button :aria-label="`进入直播 ${anchor.name}`" @click="enter(anchor)">进入直播</button></div></div></article></section><div v-if="confirmRoom" class="dialog-backdrop" @click.self="confirmRoom=null"><section class="pay-dialog" role="dialog" aria-modal="true"><div class="coin-orb">◈</div><h2>付费进入</h2><p>确认支付 {{confirmRoom.coins}} 金币进入直播？</p><small>确认后才会扣除余额</small><div><button class="ghost-button" @click="confirmRoom=null">再想想</button><button class="primary-button" @click="confirm">确认支付</button></div></section></div><p v-if="entering" class="toast">正在进入直播间</p></main></template>
